# Fixes UTF-8 corruption in src\app\vendor\(protected)\layout.tsx
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\vendor\(protected)\layout.tsx"), $bytes)
Write-Host "FIXED: src\app\vendor\(protected)\layout.tsx" -ForegroundColor Green